export function getBlogPostBySlug(slug: string): BlogPostMeta | undefined {
  return BLOG_POSTS_CATALOG.find(p => p.slug === slug);
}

export function getBlogPostsByCategory(category: string): BlogPostMeta[] {
  return BLOG_POSTS_CATALOG.filter(p => p.category === category);
}

export function getBlogPostsByBucket(bucket: string): BlogPostMeta[] {
  return BLOG_POSTS_CATALOG.filter(p => p.bucket === bucket);
}
